<script setup>
import { ref, onMounted, computed } from 'vue'
import levelCard from './components/levelCard.vue'
import levelGet from './components/levelGet.vue'

const levelList = ref(null)

onMounted(async () => {
  try {
    const data = await levelGet.methods.getLevel()
    levelList.value = data
  } catch (error) {
    console.error(error)
  }
})

const props = defineProps({
  columns: {
    type: Number,
    default: 6
  },
  gap: {
    type: Number,
    default: 0.20
  },
  gridWidth: {
    type: [Number, String],
    default: '100%'
  }
})

const containerStyle = computed(() => {
  return {
    width: typeof props.gridWidth === 'number' ? `${props.gridWidth}px` : props.gridWidth,
    margin: '0 auto',
    boxSizing: 'border-box'
  }
})

const getGridStyle = () => {
  return {
    '--column-count': props.columns,
    '--gap-rem': `${props.gap}rem`
  }
}

const sortedCardList = computed(() => {
  if (!levelList.value) return []
  const entries = Object.entries(levelList.value)
  const sortedEntries = entries.sort((a, b) => Number(b[0]) - Number(a[0]))
  return sortedEntries.map(([key, value]) => ({ key, value }))
})
</script>

<template>
  <div class="table-container">
    <div class="card-container" :style="containerStyle">
      <div v-for="({ key: groupKey, value: cardGroup }, index) in sortedCardList" :key="groupKey" class="card-group">
        <div class="group-title">
          {{ Number(groupKey).toFixed(1) }}
        </div>
        <div class="card-grid" :style="getGridStyle()">
          <levelCard
            v-for="(item, idx) in cardGroup"
            :key="idx"
            :chart-info="item"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
.table-container {
  width: 100%;
  padding: 0.2rem;
  box-sizing: border-box;
}

.card-container {
  width: 100%;
  box-sizing: border-box;
}

.card-group {
  width: 100%;
  margin-bottom: 0.24rem;
  user-select: none;
}

.group-title {
  height: 0.3rem;
  line-height: 0.3rem;
  background-color: var(--color-bg-sub);
  color: var(--color-text);
  padding: 0 0.16rem;
  font-size: 0.16rem;
  font-weight: 600;
  margin-bottom: 0.08rem;
  text-align: center;
  user-select: none;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(var(--column-count), 1fr);
  gap: var(--gap-rem);
  width: 100%;
  user-select: none;
}

.card-grid > * {
  width: 100% !important;
  box-sizing: border-box;
}
</style>